{
  "understanding": {
    "purpose": "帮助读者根据 API 错误码和错误信息判断故障含义，并找到排查和解决步骤。",
    "reading": "读者通常先定位错误码或错误信息，再横向阅读同一行的含义和解决办法；首屏能否同时呈现识别信息与含义，对快速判断尤为重要。",
    "groups": [
      "错误码与错误信息共同标识故障，适合并列扫描。",
      "含义与解决办法共同解释故障及其处理方式，应保持清晰的同行对应关系。"
    ],
    "keep_intact": [
      "错误码",
      "错误信息中的标识符",
      "含义和解决办法中的 access_token、AppID 等技术标识符"
    ],
    "may_wrap": [
      "含义中的中文说明可自然换行。",
      "解决办法中的中文步骤可自然换行；较长的解决办法形成的行高可容纳同一行中较短说明的换行。"
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [70, 175, 116, 200],
      "idea": "优先让错误码、错误信息和含义几乎完整地出现在首屏，并保留 access_token，向右滚动查看解决办法。"
    },
    {
      "name": "B",
      "widths": [70, 175, 160, 260],
      "idea": "加宽含义和解决办法以改善长段文字的阅读节奏、降低行高，代价是首屏会切入含义列且横向滚动距离更长。"
    },
    {
      "name": "C",
      "widths": [70, 120, 110, 59],
      "idea": "将四列都放入首屏以显示完整表格结构，接受错误信息和技术标识符被拆分、解决办法形成很高的窄文本列。"
    }
  ]
}
